export function multiPathVerification(paths) {
  const results = paths.map(path => path.evaluate());
  const discrepancies = [];
  for (let i = 0; i < results.length; i++) {
    for (let j = i + 1; j < results.length; j++) {
      if (!results[i].isConsistentWith(results[j])) {
        discrepancies.push({ path1: i, path2: j });
      }
    }
  }
  return discrepancies;
}